func solveSudoku(board [][]byte) {
	var rows, cols, boxes [9][9]bool
	var empties [][2]int
	for i := 0; i < 9; i++ {
		for j := 0; j < 9; j++ {
			if board[i][j] == '.' {
				empties = append(empties, [2]int{i, j})
			} else {
				d := board[i][j] - '1'
				rows[i][d] = true
				cols[j][d] = true
				boxes[i/3*3+j/3][d] = true
			}
		}
	}
	var solve func(idx int) bool
	solve = func(idx int) bool {
		if idx == len(empties) {
			return true
		}
		i, j := empties[idx][0], empties[idx][1]
		b := i/3*3 + j/3
		for d := byte(0); d < 9; d++ {
			if !rows[i][d] && !cols[j][d] && !boxes[b][d] {
				board[i][j] = d + '1'
				rows[i][d], cols[j][d], boxes[b][d] = true, true, true
				if solve(idx + 1) {
					return true
				}
				rows[i][d], cols[j][d], boxes[b][d] = false, false, false
				board[i][j] = '.'
			}
		}
		return false
	}
	solve(0)
}

class Solution {
  private boolean[][] rows = new boolean[9][9];
  private boolean[][] cols = new boolean[9][9];
  private boolean[][] boxes = new boolean[9][9];
  private int[] emptyI = new int[81];
  private int[] emptyJ = new int[81];
  private int empties = 0;

  public void solveSudoku(char[][] board) {
    for (int i = 0; i < 9; i++) {
      for (int j = 0; j < 9; j++) {
        char c = board[i][j];
        if (c == '.') {
          emptyI[empties] = i;
          emptyJ[empties] = j;
          empties++;
        } else {
          int d = c - '1';
          rows[i][d] = cols[j][d] = boxes[(i / 3) * 3 + j / 3][d] = true;
        }
      }
    }
    solve(board, 0);
  }

  private boolean solve(char[][] board, int idx) {
    if (idx == empties) {
      return true;
    }
    int i = emptyI[idx], j = emptyJ[idx];
    int b = (i / 3) * 3 + j / 3;
    for (int d = 0; d < 9; d++) {
      if (!rows[i][d] && !cols[j][d] && !boxes[b][d]) {
        board[i][j] = (char) ('1' + d);
        rows[i][d] = cols[j][d] = boxes[b][d] = true;
        if (solve(board, idx + 1)) {
          return true;
        }
        rows[i][d] = cols[j][d] = boxes[b][d] = false;
        board[i][j] = '.';
      }
    }
    return false;
  }
}

class Solution:
    def solveSudoku(self, board: List[List[str]]) -> None:
        rows = [[False] * 9 for _ in range(9)]
        cols = [[False] * 9 for _ in range(9)]
        boxes = [[False] * 9 for _ in range(9)]
        empties = []
        for i in range(9):
            for j in range(9):
                c = board[i][j]
                if c == ".":
                    empties.append((i, j))
                else:
                    d = ord(c) - ord("1")
                    rows[i][d] = cols[j][d] = boxes[(i // 3) * 3 + j // 3][d] = True

        def solve(idx: int) -> bool:
            if idx == len(empties):
                return True
            i, j = empties[idx]
            b = (i // 3) * 3 + j // 3
            for d in range(9):
                if not rows[i][d] and not cols[j][d] and not boxes[b][d]:
                    board[i][j] = chr(ord("1") + d)
                    rows[i][d] = cols[j][d] = boxes[b][d] = True
                    if solve(idx + 1):
                        return True
                    rows[i][d] = cols[j][d] = boxes[b][d] = False
                    board[i][j] = "."
            return False

        solve(0)

const solveSudoku = (board: string[][]): void => {
  const rows: boolean[][] = Array.from({ length: 9 }, () => new Array(9).fill(false));
  const cols: boolean[][] = Array.from({ length: 9 }, () => new Array(9).fill(false));
  const boxes: boolean[][] = Array.from({ length: 9 }, () => new Array(9).fill(false));
  const empties: [number, number][] = [];
  for (let i = 0; i < 9; i++) {
    for (let j = 0; j < 9; j++) {
      const c = board[i][j];
      if (c === '.') {
        empties.push([i, j]);
      } else {
        const d = c.charCodeAt(0) - '1'.charCodeAt(0);
        rows[i][d] = cols[j][d] = boxes[Math.floor(i / 3) * 3 + Math.floor(j / 3)][d] = true;
      }
    }
  }

  const solve = (idx: number): boolean => {
    if (idx === empties.length) return true;
    const [i, j] = empties[idx];
    const b = Math.floor(i / 3) * 3 + Math.floor(j / 3);
    for (let d = 0; d < 9; d++) {
      if (!rows[i][d] && !cols[j][d] && !boxes[b][d]) {
        board[i][j] = String.fromCharCode('1'.charCodeAt(0) + d);
        rows[i][d] = cols[j][d] = boxes[b][d] = true;
        if (solve(idx + 1)) return true;
        rows[i][d] = cols[j][d] = boxes[b][d] = false;
        board[i][j] = '.';
      }
    }
    return false;
  };

  solve(0);
};
